+@page "/book-appointment"
+@rendermode InteractiveServer
+@using sv_a171183809124e5cb3a474b8993115d3.Services
+@using System.ComponentModel.DataAnnotations
+@inject AppointmentService AppointmentService
+
+<h3>Book an Appointment</h3>
+
+<EditForm EditContext="editContext" OnSubmit="HandleSubmit" FormName="book-appointment">
+    <DataAnnotationsValidator />
+    <CustomValidator @ref="customValidator" />
+
+    <h4>Step 1: Patient Information</h4>
+
+    <div class="mb-3">
+        <label class="form-label">Patient Name</label>
+        <InputText class="form-control" @bind-Value="model.PatientName" />
+        <ValidationMessage For="() => model.PatientName" />
+    </div>
+
+    <div class="mb-3">
+        <label class="form-label">Email</label>
+        <InputText class="form-control" @bind-Value="model.Email" />
+        <ValidationMessage For="() => model.Email" />
+    </div>
+
+    <div class="mb-3">
+        <label class="form-label">Phone</label>
+        <InputText class="form-control" @bind-Value="model.Phone" />
+        <ValidationMessage For="() => model.Phone" />
+    </div>
+
+    <div class="mb-3">
+        <label class="form-label">Insurance Provider</label>
+        <InputSelect class="form-control" @bind-Value="model.InsuranceProvider">
+            <option value="">-- Select --</option>
+            <option value="Aetna">Aetna</option>
+            <option value="BlueCross">BlueCross</option>
+            <option value="Cigna">Cigna</option>
+            <option value="UnitedHealth">UnitedHealth</option>
+            <option value="None">None</option>
+        </InputSelect>
+        <ValidationMessage For="() => model.InsuranceProvider" />
+    </div>
+
+    @if (!showStep2)
+    {
+        <button type="button" class="btn btn-primary" @onclick="ProceedToStep2">
+            Next
+        </button>
+    }
+
+    @if (showStep2)
+    {
+        <hr />
+        <h4>Step 2: Appointment Details</h4>
+
+        <div class="mb-3">
+            <label class="form-label">Preferred Doctor</label>
+            <InputSelect class="form-control" @bind-Value="model.Doctor" @bind:after="OnDoctorOrDateChanged">
+                <option value="">-- Select --</option>
+                @foreach (var doc in doctors)
+                {
+                    <option value="@doc">@doc</option>
+                }
+            </InputSelect>
+            <ValidationMessage For="() => model.Doctor" />
+        </div>
+
+        <div class="mb-3">
+            <label class="form-label">Date</label>
+            <InputDate class="form-control" @bind-Value="model.AppointmentDate" @bind:after="OnDoctorOrDateChanged" />
+            <ValidationMessage For="() => model.AppointmentDate" />
+        </div>
+
+        <div class="mb-3">
+            <label class="form-label">Time Slot</label>
+            <InputSelect class="form-control" @bind-Value="model.TimeSlot">
+                <option value="">-- Select --</option>
+                @foreach (var slot in availableSlots)
+                {
+                    <option value="@slot">@slot</option>
+                }
+            </InputSelect>
+            <ValidationMessage For="() => model.TimeSlot" />
+        </div>
+
+        <div class="mb-3">
+            <label class="form-label">Reason for Visit</label>
+            <InputTextArea class="form-control" @bind-Value="model.ReasonForVisit" />
+            <ValidationMessage For="() => model.ReasonForVisit" />
+        </div>
+
+        <button type="button" class="btn btn-secondary me-2" @onclick="CheckAvailability" disabled="@isSubmitting">
+            @(isSubmitting ? "Checking..." : "Check Availability")
+        </button>
+
+        @if (bookingConfirmed)
+        {
+            <div class="alert alert-success mt-3">Appointment booked successfully!</div>
+        }
+    }
+</EditForm>
+
+@code {
+    private EditContext editContext = null!;
+    private AppointmentFormModel model = new();
+    private CustomValidator? customValidator;
+
+    private bool showStep2;
+    private bool isSubmitting;
+    private bool bookingConfirmed;
+    private List<string> doctors = new();
+    private List<string> availableSlots = new();
+
+    protected override async Task OnInitializedAsync()
+    {
+        editContext = new EditContext(model);
+        doctors = await AppointmentService.GetDoctorsAsync();
+    }
+
+    private void ProceedToStep2()
+    {
+        customValidator?.ClearErrors();
+
+        // Validate only step 1 fields
+        var isValid = editContext.Validate();
+        if (!isValid)
+        {
+            // Check if errors are only on step 2 fields (shouldn't be since step 2 not shown yet)
+            return;
+        }
+
+        // Step 1 fields use [Required] so Validate() will catch them.
+        // But step 2 fields also have [Required] — we need partial validation.
+        // Since step 2 isn't shown yet, those fields are empty and will fail.
+        // Use manual check for step 1 fields only.
+        var step1Valid = !string.IsNullOrWhiteSpace(model.PatientName)
+            && !string.IsNullOrWhiteSpace(model.Email)
+            && !string.IsNullOrWhiteSpace(model.Phone)
+            && !string.IsNullOrWhiteSpace(model.InsuranceProvider)
+            && new EmailAddressAttribute().IsValid(model.Email);
+
+        if (step1Valid)
+        {
+            showStep2 = true;
+        }
+        else
+        {
+            // Trigger validation to show messages on step 1 fields
+            editContext.Validate();
+        }
+    }
+
+    private async Task OnDoctorOrDateChanged()
+    {
+        if (!string.IsNullOrWhiteSpace(model.Doctor) && model.AppointmentDate.HasValue)
+        {
+            availableSlots = await AppointmentService.GetAvailableSlotsAsync(
+                model.Doctor, DateOnly.FromDateTime(model.AppointmentDate.Value));
+        }
+    }
+
+    private async Task CheckAvailability()
+    {
+        customValidator?.ClearErrors();
+        bookingConfirmed = false;
+
+        if (!editContext.Validate())
+            return;
+
+        // Additional check: date must be in the future
+        if (model.AppointmentDate.HasValue && model.AppointmentDate.Value.Date <= DateTime.Today)
+        {
+            customValidator?.DisplayErrors(new Dictionary<string, List<string>>
+            {
+                [nameof(model.AppointmentDate)] = new() { "Date must be in the future" }
+            });
+            return;
+        }
+
+        isSubmitting = true;
+        try
+        {
+            var errors = await AppointmentService.ValidatePatientAsync(
+                model.Email!,
+                model.InsuranceProvider!,
+                model.Doctor!,
+                model.TimeSlot!);
+
+            if (errors.Count > 0)
+            {
+                customValidator?.DisplayErrors(errors);
+            }
+            else
+            {
+                bookingConfirmed = true;
+            }
+        }
+        finally
+        {
+            isSubmitting = false;
+        }
+    }
+
+    private async Task HandleSubmit()
+    {
+        // Form submission is handled by CheckAvailability button
+        await CheckAvailability();
+    }
+
+    private class AppointmentFormModel
+    {
+        [Required(ErrorMessage = "Patient name is required")]
+        public string? PatientName { get; set; }
+
+        [Required(ErrorMessage = "Email is required")]
+        [EmailAddress(ErrorMessage = "Invalid email format")]
+        public string? Email { get; set; }
+
+        [Required(ErrorMessage = "Phone is required")]
+        public string? Phone { get; set; }
+
+        [Required(ErrorMessage = "Insurance provider is required")]
+        public string? InsuranceProvider { get; set; }
+
+        [Required(ErrorMessage = "Doctor is required")]
+        public string? Doctor { get; set; }
+
+        [Required(ErrorMessage = "Date is required")]
+        public DateTime? AppointmentDate { get; set; }
+
+        [Required(ErrorMessage = "Time slot is required")]
+        public string? TimeSlot { get; set; }
+
+        [Required(ErrorMessage = "Reason for visit is required")]
+        [MaxLength(500, ErrorMessage = "Reason must be 500 characters or fewer")]
+        public string? ReasonForVisit { get; set; }
+    }
+}
