private void ProceedToStep2()
{
    customValidator?.ClearErrors();

    // Manually validate step 1 fields only (full Validate() would flag empty step 2 fields)
    var errors = new Dictionary<string, List<string>>();

    if (string.IsNullOrWhiteSpace(model.PatientName))
        errors[nameof(model.PatientName)] = new() { "Patient name is required" };

    if (string.IsNullOrWhiteSpace(model.Email))
        errors[nameof(model.Email)] = new() { "Email is required" };
    else if (!new EmailAddressAttribute().IsValid(model.Email))
        errors[nameof(model.Email)] = new() { "Invalid email format" };

    if (string.IsNullOrWhiteSpace(model.Phone))
        errors[nameof(model.Phone)] = new() { "Phone is required" };

    if (string.IsNullOrWhiteSpace(model.InsuranceProvider))
        errors[nameof(model.InsuranceProvider)] = new() { "Insurance provider is required" };

    if (errors.Count > 0)
    {
        customValidator?.DisplayErrors(errors);
        return;
    }

    showStep2 = true;
}

